  frontend_port                  = 80
  backend_port                    = 80
  frontend_ip_configuration_name = "example-fip"
  backend_address_pool_ids        = [azurerm_lb_backend_address_pool.example.id]
}

resource "azurerm_virtual_machine_scale_set" "example" {
  name                = var.vmss_name
  location            = azurerm_resource_group.example.location
  resource_group_name = azurerm_resource_group.example.name
  upgrade_policy_mode = "Rolling"

  automatic_os_upgrade_policy {
    disable_automatic_rollback = false
    enable_automatic_os_upgrade = true
    enable_automatic_vm_restart  = true
  }

  rolling_upgrade_policy {
    max_batch_size              = 20
    max_unhealthy_instances     = 20
    max_unhealthy_upgraded_instances = 20
    pause_time_between_batches = "PT0S"
  }

  sku {
    name     = "Standard_DS2_v2"
    tier     = "Standard"
    capacity = 2
  }

  storage_profile_image_reference {
    publisher = "Canonical"
    offer     = "UbuntuServer"
    sku       = "16.04-LTS"
    version   = "latest"
  }

  storage_profile_os_disk {
    caching              = "ReadWrite"
    create_option        = "FromImage"
    managed_disk_type    = "Standard_LRS"
  }

  os_profile {
    admin_username = var.admin_username
    admin_password = var.admin_password
    computer_name_prefix = "example"
  }

  os_profile_linux_config {
    disable_password_authentication = false
  }

  network_profile {
    name    = "example-np"
    primary = true

    ip_configuration {
      name                                   = "example-ip"
      primary                               = true
      subnet_id                             = azurerm_subnet.example.id
      load_balancer_backend_address_pool_ids = [azurerm_lb_backend_address_pool.example.id]
    }
  }
}

resource "azurerm_monitor_autoscale_setting" "example" {
  name                = "example-asc"
  resource_group_name = azurerm_resource_group.example.name
  location            = azurerm_resource_group.example.location
  target_resource_id  = azurerm_virtual_machine_scale_set.example.id

  profile {
    name = "example-profile"

    capacity {
      default = 2
      minimum = 2
      maximum = 10
    }

    rule {
      metric_trigger {
        metric_name              = "Percentage CPU"
        namespace                 = "microsoft.compute/virtualmachinescalesets"
        resource_id               = azurerm_virtual_machine_scale_set.example.id
        operator                  = "GreaterThan"
        statistic                 = "Average"
        threshold                 = 80
        time_aggregation          = "Average"
        time_grain                 = "PT1M"
        time_window                = "PT5M"
        metric_resource_id         = azurerm_virtual_machine_scale_set.example.id
        divide_per_instance       = false
      }

      scale_action {
        direction = "Increase"
        type      = "ChangeCount"
        value     = "1"
        cooldown  = "PT5M"
      }
    }

    rule {
      metric_trigger {
        metric_name              = "Percentage CPU"
        namespace                 = "microsoft.compute/virtualmachinescalesets"
        resource_id               = azurerm_virtual_machine_scale_set.example.id
        operator                  = "LessThan"
        statistic                 = "Average"
        threshold                 = 20
        time_aggregation          = "Average"
        time_grain                 = "PT1M"
        time_window                = "PT5M"
        metric_resource_id         = azurerm_virtual_machine_scale_set.example.id
        divide_per_instance       = false
      }

      scale_action {
        direction = "Decrease"
        type      = "ChangeCount"
        value     = "1"
        cooldown  = "PT5M"
      }
    }
  }
}

