  bucket_name = google_storage_bucket.gcp_bucket.name
  enable_cdn = true
}

resource "google_compute_url_map" "gcp_url_map" {
  name            = var.gcp_url_map_name
  default_service = google_compute_backend_bucket.gcp_backend_bucket.self_link
}

