    Statement = [
      {
        Sid       = "AllowS3Read"
        Effect    = "Allow"
        Action    = [
          "s3:GetObject",
          "s3:ListBucket",
        ]
        Resource = [
          "arn:aws:s3:::${var.bucket_name}",
          "arn:aws:s3:::${var.bucket_name}/*",
